import {api} from './catalog.js';
import {resourceCard} from './multimedia.js';
const form=document.querySelector('#resource-search'),results=document.querySelector('#resource-results'),count=document.querySelector('#resource-count'),errorBox=document.querySelector('#resource-error'),pagination=document.querySelector('#resource-pagination');
let controller,preview;
for(const [key,value] of new URLSearchParams(location.search))if(form.elements[key])form.elements[key].value=value;
async function search(page=1){controller?.abort();controller=new AbortController();errorBox.textContent='';count.textContent='Đang tìm tư liệu…';const params=new URLSearchParams();for(const [k,v] of new FormData(form))if(v)params.set(k,v);params.set('page',page);history.replaceState(null,'','?'+params);try{const data=await api('/search?'+params,{signal:controller.signal});results.innerHTML=data.items.map(resourceCard).join('')||'<p class="empty-resources">Chưa tìm thấy tư liệu phù hợp. Hãy mở rộng bộ lọc.</p>';count.textContent=data.total+' tư liệu phù hợp';pagination.innerHTML=`${page>1?'<button class="button button-outline" data-page="'+(page-1)+'">← Trang trước</button>':''}<span>Trang ${page} / ${Math.max(1,Math.ceil(data.total/data.pageSize))}</span>${data.hasMore?'<button class="button button-outline" data-page="'+(page+1)+'">Trang sau →</button>':''}`;}catch(error){if(error.name==='AbortError')return;errorBox.textContent=error.message;count.textContent='Chưa tìm được tư liệu';}}
form.addEventListener('submit',e=>{e.preventDefault();search();});form.addEventListener('reset',()=>setTimeout(()=>search(),0));pagination.addEventListener('click',e=>{const button=e.target.closest('[data-page]');if(button)search(Number(button.dataset.page));});
document.querySelector('#cbir-file').addEventListener('change',e=>{const file=e.target.files[0],img=document.querySelector('#cbir-preview');if(preview)URL.revokeObjectURL(preview);if(file){preview=URL.createObjectURL(file);img.src=preview;img.hidden=false;}else img.hidden=true;});
async function imageSearch(id){const button=document.querySelector('#cbir-form button'),info=document.querySelector('#cbir-info');button.disabled=true;info.textContent='Đang so sánh màu sắc…';controller?.abort();errorBox.textContent='';try{const file=document.querySelector('#cbir-file').files[0];if(!id&&(!file||file.size>8*1024*1024))throw new Error('Chọn ảnh JPG, PNG hoặc WebP tối đa 8 MiB.');const data=await api(id?'/search/similar?id='+encodeURIComponent(id):'/search/image',id?{}:{method:'POST',headers:{'Content-Type':file.type},body:file,signal:AbortSignal.timeout(60000)});results.innerHTML=data.items.map(resourceCard).join('')||'<p>Chưa có ảnh phù hợp trong chỉ mục.</p>';count.textContent=data.items.length+' ảnh tương tự nhất';pagination.innerHTML='';info.textContent=`Đối chiếu ${data.indexedImages} ảnh · ${data.elapsedMs} ms. Xếp hạng bằng histogram RGB và cosine; điểm phản ánh màu sắc, không xác định cùng hiện vật.`;}catch(error){info.textContent=error.message;}finally{button.disabled=false;}}
document.querySelector('#cbir-form').addEventListener('submit',e=>{e.preventDefault();imageSearch();});const similar=new URLSearchParams(location.search).get('similar');if(similar){document.querySelector('#image-search').open=true;await imageSearch(similar);}else await search(Number(new URLSearchParams(location.search).get('page'))||1);
